142:                                .append("0x")
143:                                .append(toHexString(vp.getPropId()))
144:                                .append(" ignored")
145:                                .toString());
146:                }
147:            } else {
148:                synchronized (mLock) {
149:                    mSensorTypeToConfig.append(sensorType, vp);
150:                }
151:            }
152:        }
153:    }
154:
155:    /**
156:     * Returns a unique token to be used to map this property to a higher-level sensor
157:     * This token will be stored in {@link DiagnosticHalService#mSensorTypeToConfig} to allow
158:     * callers to go from unique sensor identifiers to HalPropConfig objects
159:     * @param propConfig The property config
160:     * @return SENSOR_TYPE_INVALID or a locally unique token
161:     */
162:    protected int getTokenForProperty(HalPropConfig propConfig) {
163:        int propId = propConfig.getPropId();
164:        synchronized (mLock) {
165:            switch (propId) {
166:                case VehicleProperty.OBD2_LIVE_FRAME:
167:                    mDiagnosticCapabilities.setSupported(propId);
168:                    mVehiclePropertyToConfig.put(propId, propConfig);
169:                    Slogf.i(CarLog.TAG_DIAGNOSTIC, "configArray for OBD2_LIVE_FRAME is "
170:                            + Arrays.toString(propConfig.getConfigArray()));
171:                    return CarDiagnosticManager.FRAME_TYPE_LIVE;
172:                case VehicleProperty.OBD2_FREEZE_FRAME:
173:                    mDiagnosticCapabilities.setSupported(propId);
174:                    mVehiclePropertyToConfig.put(propId, propConfig);
175:                    Slogf.i(CarLog.TAG_DIAGNOSTIC, "configArray for OBD2_FREEZE_FRAME is "
176:                            + Arrays.toString(propConfig.getConfigArray()));
177:                    return CarDiagnosticManager.FRAME_TYPE_FREEZE;
178:                case VehicleProperty.OBD2_FREEZE_FRAME_INFO:
179:                    mDiagnosticCapabilities.setSupported(propId);
180:                    return propId;
181:                case VehicleProperty.OBD2_FREEZE_FRAME_CLEAR:
182:                    mDiagnosticCapabilities.setSupported(propId);
183:                    int[] configArray = propConfig.getConfigArray();
184:                    Slogf.i(CarLog.TAG_DIAGNOSTIC, "configArray for OBD2_FREEZE_FRAME_CLEAR is "
185:                            + Arrays.toString(configArray));
186:                    if (configArray.length < 1) {
187:                        Slogf.e(CarLog.TAG_DIAGNOSTIC, "property 0x%x does not specify whether it "
188:                                + "supports selective clearing of freeze frames. assuming it does "
189:                                + "not.", propId);
190:                    } else {
191:                        if (configArray[0] == 1) {
192:                            mDiagnosticCapabilities.setSupported(OBD2_SELECTIVE_FRAME_CLEAR);
193:                        }
194:                    }
195:                    return propId;
196:                default:
197:                    return NOT_SUPPORTED_PROPERTY;
198:            }
199:        }
200:    }
