209:    private static class EventListener extends ICarPropertyEventListener.Stub{
210:        private final CarPropertyService mService;
211:        private List<CarPropertyEvent> mEvents;
212:        private Exception mException;
213:
214:        EventListener(CarPropertyService service) {
215:            mService = service;
216:        }
217:
218:        @Override
219:        public void onEvent(List<CarPropertyEvent> events) throws RemoteException {
220:            CountDownLatch latch = new CountDownLatch(1);
221:            new Thread(() -> {
222:                // Call a function in CarPropertyService to make sure there is no dead lock. This
223:                // call doesn't actually do anything. We must use a new thread here because
224:                // the same thread can obtain the same lock again even if there is a dead lock.
225:                mService.getReadPermission(0);
226:                latch.countDown();
227:            }, "onEventThread").start();
228:            try {
229:                if (!latch.await(5, TimeUnit.SECONDS)) {
230:                    mException = new Exception("timeout waiting for getReadPermission, dead lock?");
231:                    return;
232:                }
233:            } catch (InterruptedException e) {
234:                Thread.currentThread().interrupt();
235:                mException = new Exception("waiting for onEvent thread interrupted");
236:                return;
237:            }
238:            mEvents = events;
239:        }
240:
241:        List<CarPropertyEvent> getEvents() throws Exception {
242:            if (mException != null) {
243:                throw mException;
244:            }
245:            return mEvents;
246:        }
247:    }
248:
249:    @Test
250:    public void testOnEventCallback_MustNotHaveDeadLock() throws Exception {
251:        // This test checks that CarPropertyService must not hold any lock while calling
252:        // ICarPropertyListener's onEvent callback, otherwise it might cause dead lock if
253:        // the callback calls another function in CarPropertyService that requires the same lock.
254:
255:        // We don't care about the result for getReadPermission so just return an empty map.
256:        when(mHalService.getPermissionsForAllProperties()).thenReturn(
257:                new SparseArray<Pair<String, String>>());
258:        mService.init();
259:
260:        // Initially HVAC_TEMP is not subscribed, so should return -1.
261:        when(mHalService.getSampleRate(HVAC_TEMP)).thenReturn(-1f);
262:        CarPropertyValue<Float> value = new CarPropertyValue<Float>(HVAC_TEMP, 0, 1.0f);
263:        when(mHalService.getPropertySafe(HVAC_TEMP, 0)).thenReturn(value);
264:        EventListener listener = new EventListener(mService);
265:
266:        mService.registerListener(HVAC_TEMP, /* rate= */ SENSOR_RATE_ONCHANGE, listener);
267:        List<CarPropertyEvent> events = List.of(new CarPropertyEvent(0, value));
268:        mService.onPropertyChange(events);
269:
270:        assertThat(listener.getEvents()).isEqualTo(events);
271:    }
