329:                        break;
330:                    case CarPropertyConfig.VEHICLE_PROPERTY_ACCESS_READ:
331:                        Assert.assertTrue(readPermission != null && writePermission == null);
332:                        break;
333:                    default:
334:                        Assert.fail(String.format("PropertyId: %d has an invalid access model: %d",
335:                                cfg.getPropertyId(), accessModel));
336:                }
337:            }
