341:    private class GearEventTestCallback implements CarPropertyEventCallback {
342:        private long mTimestamp = 0L;
343:
344:        @Override
345:        public void onChangeEvent(CarPropertyValue carPropertyValue) {
346:            if (carPropertyValue.getPropertyId() != GEAR_PROPERTY_ID) {
347:                return;
348:            }
349:            if (carPropertyValue.getStatus() == CarPropertyValue.STATUS_AVAILABLE) {
350:                Assert.assertTrue("Received events out of oder",
351:                        mTimestamp <= carPropertyValue.getTimestamp());
352:                mTimestamp = carPropertyValue.getTimestamp();
353:            }
354:        }
355:
356:        @Override
357:        public void onErrorEvent(final int propertyId, final int zone) {
358:            Assert.fail("Error: propertyId: x0" + toHexString(propertyId) + " areaId: " + zone);
359:        }
360:    }
