362:    /**
363:     * Inject events from vehicle side. It change the value of property even the property is a
364:     * read_only property such as GEAR_SELECTION. It only works with Google VHAL.
365:     */
366:    private void injectEventFromVehicleSide(List<CarPropertyValue> expectedEvents,
367:            CarPropertyManager propMgr) {
368:        for (CarPropertyValue propertyValue : expectedEvents) {
369:            Object[] values = new Object[3];
370:            int propId;
371:            // The order of values is matter
372:            if (propertyValue.getValue() instanceof Integer) {
373:                propId = SET_INT_FROM_VEHICLE;
374:                values[0] = propertyValue.getPropertyId();
375:                values[1] = propertyValue.getValue();
376:                values[2] = propertyValue.getTimestamp() + SystemClock.elapsedRealtimeNanos();
377:            } else if (propertyValue.getValue() instanceof Float) {
378:                values[0] = propertyValue.getPropertyId();
379:                values[1] = propertyValue.getTimestamp() + SystemClock.elapsedRealtimeNanos();
380:                values[2] = propertyValue.getValue();
381:                propId = SET_FLOAT_FROM_VEHICLE;
382:            } else if (propertyValue.getValue() instanceof Boolean) {
383:                propId = SET_BOOLEAN_FROM_VEHICLE;
384:                values[1] = propertyValue.getPropertyId();
385:                values[0] = propertyValue.getValue();
386:                values[2] = propertyValue.getTimestamp() + SystemClock.elapsedRealtimeNanos();
387:            } else {
388:                throw new IllegalArgumentException(
389:                        "Unexpected property type for property " + propertyValue.getPropertyId());
390:            }
391:            propMgr.setProperty(Object[].class, propId, propertyValue.getAreaId(), values);
392:        }
393:    }
