44:@RunWith(AndroidJUnit4.class)
45:@LargeTest
46:public class CarDiagnosticTest extends E2eCarTestBase {
47:
48:    private static final String TAG = Utils.concatTag(CarDiagnosticTest.class);
49:
50:    private static final Duration TEST_TIME_OUT = Duration.ofMinutes(5);
51:
52:    private static final String CAR_DIAGNOSTIC_TEST_JSON = "car_diagnostic_test.json";
53:
54:    private static final SparseIntArray DIAGNOSTIC_PROPERTY_MAP;
55:
56:    static {
57:        DIAGNOSTIC_PROPERTY_MAP = new SparseIntArray();
58:        DIAGNOSTIC_PROPERTY_MAP.append(
59:                CarDiagnosticManager.FRAME_TYPE_LIVE, VehicleProperty.OBD2_LIVE_FRAME);
60:        DIAGNOSTIC_PROPERTY_MAP.append(
61:                CarDiagnosticManager.FRAME_TYPE_FREEZE, VehicleProperty.OBD2_FREEZE_FRAME);
62:    }
63:
64:    private class CarDiagnosticListner implements CarDiagnosticManager.OnDiagnosticEventListener {
65:
66:        private VhalEventVerifier mVerifier;
67:
68:        CarDiagnosticListner(VhalEventVerifier verifier) {
69:            mVerifier = verifier;
70:        }
71:
72:        @Override
73:        public void onDiagnosticEvent(CarDiagnosticEvent event) {
74:            mVerifier.verify(fromCarDiagnosticEvent(event));
75:        }
76:    }
77:
78:    private static CarPropertyValue<VehiclePropValue.RawValue> fromCarDiagnosticEvent(
79:            final CarDiagnosticEvent event) {
80:        int prop = DIAGNOSTIC_PROPERTY_MAP.get(event.frameType);
81:        VehiclePropValueBuilder builder = VehiclePropValueBuilder.newBuilder(prop);
82:
83:        for (int i = 0; i <= IntegerSensorIndex.LAST_SYSTEM; i++) {
84:            builder.addIntValue(event.getSystemIntegerSensor(i, 0));
85:        }
86:        for (int i = 0; i <= FloatSensorIndex.LAST_SYSTEM; i++) {
87:            builder.addFloatValue(event.getSystemFloatSensor(i, 0));
88:        }
89:
90:        builder.setStringValue(event.dtc);
91:        return new CarPropertyValue<>(prop, 0, builder.build().value);
92:    }
93:
94:    @Test
95:    public void testDiagnosticEvents() throws Exception {
96:        Log.d(TAG, "Prepare Diagnostic test data");
97:        List<CarPropertyValue> expectedEvents = getExpectedEvents(CAR_DIAGNOSTIC_TEST_JSON);
98:        VhalEventVerifier verifier = new VhalEventVerifier(expectedEvents);
99:
100:        CarDiagnosticManager diagnosticManager = (CarDiagnosticManager) mCar.getCarManager(
101:                Car.DIAGNOSTIC_SERVICE);
102:
103:        CarDiagnosticListner listner = new CarDiagnosticListner(verifier);
104:
105:        assertTrue("Failed to register for OBD2 diagnostic live frame.",
106:                   diagnosticManager.registerListener(listner,
107:                                                      CarDiagnosticManager.FRAME_TYPE_LIVE,
108:                                                      CarSensorManager.SENSOR_RATE_NORMAL));
109:        assertTrue("Failed to register for OBD2 diagnostic freeze frame.",
110:                   diagnosticManager.registerListener(listner,
111:                                                      CarDiagnosticManager.FRAME_TYPE_FREEZE,
112:                                                      CarSensorManager.SENSOR_RATE_NORMAL));
113:
114:        File sharedJson = makeShareable(CAR_DIAGNOSTIC_TEST_JSON);
115:        Log.d(TAG, "Send command to VHAL to start generation");
116:        VhalEventGenerator diagnosticGenerator =
117:                new JsonVhalEventGenerator(mVehicle).setJsonFile(sharedJson);
118:        diagnosticGenerator.start();
119:
120:        Log.d(TAG, "Receiving and verifying VHAL events");
121:        verifier.waitForEnd(TEST_TIME_OUT.toMillis());
122:
123:        Log.d(TAG, "Send command to VHAL to stop generation");
124:        diagnosticGenerator.stop();
125:        diagnosticManager.unregisterListener(listner);
126:
127:        assertTrue("Detected mismatched events: " + verifier.getResultString(),
128:                    verifier.getMismatchedEvents().isEmpty());
129:    }
130:}

